import subprocess, itertools
opts=["fields","bytes","characters","lines","delimiter","regex","replace-delimiter","trim","fixed-memory"]
def first_err(args):
    p=subprocess.run(["./executable"]+args, input=b"a\n", capture_output=True)
    return p.stderr.decode(errors='replace')
wins={o:0 for o in opts}  # wins = queried earlier (its error shows even if listed second)
results=[]
for a,b in itertools.combinations(opts,2):
    # put B first in argv, A second; if error mentions A then A queried before B regardless position
    e=first_err([f"--{b}=", f"--{a}="])
    if f"--{a}'" in e:
        earlier=a
    elif f"--{b}'" in e:
        earlier=b
    else:
        earlier=f"? {e[:80]!r}"
    results.append((a,b,earlier))
    if earlier in wins: wins[earlier]+=1
for r in results: print(r)
print("order by wins desc:", sorted(wins.items(), key=lambda kv:-kv[1]))
PY
