{"command":"python3 <<'PY'
import subprocess, itertools, json, sys
alpha=['{','}','1','x']
specs=[]
for L in range(1,6):
    for t in itertools.product(alpha, repeat=L):
        specs.append(''.join(t))
data={}
for i,s in enumerate(specs):
    p=subprocess.run(["./executable","-d","-","-f",s], input=b"a-b-c\n", capture_output=True)
    err=p.stderr.decode(errors='replace')
    # normalize panic tid
    import re
    err=re.sub(r"thread 'main' \(\d+\)", "thread 'main' (TID)", err)
    data[s]=[p.returncode, p.stdout.decode(), err]
    if i%400==0: print(i, flush=True)
json.dump(data, open("/tmp/format_data.json","w"))
print("done", len(data))
# summary categories
from collections import Counter
c=Counter()
for s,(rc,out,err) in data.items():
    if rc==0: c['ok']+=1
    elif rc==-6: c['panic']+=1
    else:
        msg=err.strip().split(': ',1)[-1]
        c[msg]+=1
for k,v in c.most_common(20): print(v,k)
PY
"}

