import json, re

class ParseErr(Exception): pass
class PanicEx(Exception): pass
class OOBEx(Exception):
    def __init__(self, v): self.v=v

def parse_number(s):
    # emulate rust i64 parse for dataset simple strings
    if not re.fullmatch(r'[+-]?\d+', s or ''):
        raise ParseErr(f"Not a number `{s}`")
    v=int(s)
    if v==0:
        raise ParseErr("Zero is not a valid field")
    return v

def parse_bound_item(field):
    if field=="":
        raise ParseErr("Field format error: empty field")
    # split fallback at first =
    if '=' in field:
        main, fb = field.split('=',1)
    else:
        main, fb = field, None
    if ':' in main:
        l,r = main.split(':',1)
        if l=="" and r=="":
            if fb is None:
                raise ParseErr("Field format error, no numbers next to `:`")
            left=1; right=None
        else:
            left = 1 if l=="" else parse_number(l)
            right = None if r=="" else parse_number(r)
        return (left,right,fb)
    else:
        v = 1 if main=="" else parse_number(main)
        return (v,v,fb)

def parse_bounds_list(s):
    if s=="":
        raise ParseErr("UserBoundsList must contain at least one UserBounds")
    return [parse_bound_item(f) for f in s.split(',')]

def unescape(raw):
    out=""; i=0
    while i<len(raw):
        if raw[i:i+2]=="}}": out+="}"; i+=2
        elif raw[i:i+2]=="{{": out+="{"; i+=2
        else: out+=raw[i]; i+=1
