use std::io::Write;

#[derive(Debug)]
pub enum AppError {
    /// printed as-is + "\n" (parse errors, CLI errors, "argument is not a UTF-8 string")
    Plain(String),
    /// printed as "tuc: runtime error. {msg}\n"
    Runtime(String),
    /// printed as "Error: {msg}\n"
    Generic(String),
    /// io errors during read/write: printed as "Error: {io}\n" unless BrokenPipe
    Io(std::io::Error),
}

pub type AppResult<T> = Result<T, AppError>;

impl From<std::io::Error> for AppError {
    fn from(e: std::io::Error) -> Self {
        AppError::Io(e)
    }
}

impl AppError {
    pub fn plain(s: String) -> Self {
        AppError::Plain(s)
    }
    pub fn runtime(s: String) -> Self {
        AppError::Runtime(s)
    }
    pub fn generic(s: String) -> Self {
        AppError::Generic(s)
    }
    pub fn oob_display(disp: &str) -> Self {
        AppError::Generic(format!("Out of bounds: {}", disp))
    }
    pub fn left_gt_right() -> Self {
        AppError::Generic("Field left value cannot be greater than right value".to_string())
    }
    pub fn is_broken_pipe(&self) -> bool {
        matches!(self, AppError::Io(e) if e.kind() == std::io::ErrorKind::BrokenPipe)
    }
    pub fn render(&self) -> String {
        match self {
            AppError::Plain(s) => format!("{}\n", s),
            AppError::Runtime(s) => format!("tuc: runtime error. {}\n", s),
            AppError::Generic(s) => format!("Error: {}\n", s),
            AppError::Io(e) => format!("Error: {}\n", e),
        }
    }
}

/// Emulate a Rust panic (panic=abort) of the reference: print panic message
/// to stderr and abort with SIGABRT. Buffered stdout is intentionally
/// not flushed (the caller's BufWriter is leaked by abort).
pub fn fake_panic(location: &str, msg: &str) -> ! {
    let pid = std::process::id();
    let text = format!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        pid, location, msg
    );
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(text.as_bytes());
    let _ = lock.flush();
    std::process::abort();
}

