use crate::errors::{AppError, AppResult};
use std::io::{BufWriter, StdoutLock, Write};

pub struct Out {
    w: BufWriter<StdoutLock<'static>>,
}

impl Out {
    pub fn new() -> Self {
        Out {
            w: BufWriter::with_capacity(8192, std::io::stdout().lock()),
        }
    }
    pub fn write(&mut self, bytes: &[u8]) -> AppResult<()> {
        self.w.write_all(bytes).map_err(AppError::Io)
    }
    pub fn write_byte(&mut self, b: u8) -> AppResult<()> {
        self.w.write_all(&[b]).map_err(AppError::Io)
    }
    pub fn flush(&mut self) -> AppResult<()> {
        self.w.flush().map_err(AppError::Io)
    }
    /// Flush ignoring any error (used before reporting a processing error).
    pub fn flush_ignore(&mut self) {
        let _ = self.w.flush();
    }
}
