    pub fn bounds(&self) -> Vec<&UserBound> {
        self.segs
            .iter()
            .filter_map(|s| match s {
                Seg::Bound(b) => Some(b),
                _ => None,
            })
            .collect()
    }
    pub fn has_nonempty_literal(&self) -> bool {
        self.segs.iter().any(|s| matches!(s, Seg::Lit(t) if !t.is_empty()))
    }
    pub fn default_all() -> Self {
        BoundsSpec {
            segs: vec![Seg::Bound(UserBound {
                left: 1,
                right: None,
                fallback: None,
            })],
            is_format: false,
        }
    }
}

