    if field.is_empty() {
        return Err("Field format error: empty field".to_string());
    }
    let (main, fallback) = match field.find('=') {
        Some(i) => (&field[..i], Some(field[i + 1..].as_bytes().to_vec())),
        None => (field, None),
    };
    let bound = if let Some(ci) = main.find(':') {
        let l = &main[..ci];
        let r = &main[ci + 1..];
        if l.is_empty() && r.is_empty() {
            if fallback.is_none() {
                return Err("Field format error, no numbers next to `:`".to_string());
            }
            UserBound {
                left: 1,
                right: None,
                fallback: fallback.clone(),
            }
