fn parse_format(s: &str) -> Result<BoundsSpec, String> {
    let bytes = s.as_bytes();
    let n = bytes.len();
    let mut segs: Vec<Seg> = Vec::new();
    let mut i = 0usize;
    let mut in_bound = false;
    let mut lit: Vec<u8> = Vec::new();
    let mut buf: Vec<u8> = Vec::new();
