    while i < n {
        let c = bytes[i];
        let nxt = if i + 1 < n { bytes[i + 1] } else { 0 };
        if !in_bound {
            if c == b'{' && nxt == b'{' {
                lit.push(b'{');
                i += 2;
            } else if c == b'{' {
