                if !seg.is_empty() {
                    segs.push(Seg::Lit(seg));
                }
                buf.clear();
                i += 1;
            } else if c == b'}' && nxt == b'}' {
                buf.extend_from_slice(b"}}");
                i += 2;
            } else if c == b'}' {
                let content = String::from_utf8_lossy(&buf).into_owned();
                let bounds = if content.is_empty() {
                    return Err("Field format error: empty field".to_string());
                } else {
                    parse_bounds_list(&content)?
                };
                for b in bounds {
                    segs.push(Seg::Bound(b));
                    any_bound = true;
                }
                in_bound = false;
                i += 1;
            } else {
                buf.push(c);
                i += 1;
            }
        }
    }
    if in_bound {
        return Err("Field format error: missing closing parenthesis".to_string());
    }
    if !lit.is_empty() {
        segs.push(Seg::Lit(lit));
    }
    if !any_bound {
