                return Ok(Some(val));
            }
        }
        let prefix = "--fallback-oob=";
        for idx in 0..self.vec.len() {
            let arg = match os_to_str(&self.vec[idx]) {
                Some(a) => a.to_string(),
                None => continue,
            };
            if arg.starts_with(prefix) {
