    let replace: Option<String> = args.opt_value(&["-r", "--replace-delimiter"])?;
    let fixed_memory: Option<u64> = args.opt_parsed(&["-M", "--fixed-memory"], |s| {
        s.parse::<u64>().map_err(|e| e.to_string())
    })?;
    let join_flag = args.contains(&["-j", "--join"]);
    let no_join_flag = args.contains(&["--no-join"]);
