    pub fn eol(&self) -> u8 {
        if self.zero {
            0
        } else {
            b'\n'
        }
    }
}

pub enum ParseOutcome {
    Opt(Opt),
    Help,
    Version,
}

/// A pico-args-like argument store.
struct Args {
    vec: Vec<OsString>,
}

fn os_to_str(s: &OsString) -> Option<&str> {
    s.to_str()
}

impl Args {
    /// True if any of `keys` is present; removes the matched occurrence.
    /// Short keys are searched before long keys (in the order given);
    /// a short key may be found inside a combined short cluster.
    fn contains(&mut self, keys: &[&str]) -> bool {
        for key in keys {
            let is_short = key.len() == 2 && key.starts_with('-');
            for idx in 0..self.vec.len() {
                let arg = match os_to_str(&self.vec[idx]) {
                    Some(a) => a.to_string(),
                    None => continue,
                };
                if arg == *key {
                    self.vec.remove(idx);
                    return true;
                }
                if is_short {
                    let kc = key.as_bytes()[1];
                    let ab = arg.as_bytes();
                    if ab.len() > 2 && ab[0] == b'-' && ab[1] != b'-' {
                        if let Some(pos) = ab[1..].iter().position(|&b| b == kc) {
                            let pos = pos + 1;
                            let mut new = arg.clone();
                            new.remove(pos);
                            if new == "-" {
                                self.vec.remove(idx);
                            } else {
                                self.vec[idx] = OsString::from(new);
                            }
                            return true;
                        }
                    }
                }
            }
        }
        false
    }

    /// Extract an option value.
    /// Pass A: bare exact key tokens (keys searched in order).
    /// Pass B: `key=value` / attached short forms (keys searched in order).
    fn opt_value(&mut self, keys: &[&str]) -> AppResult<Option<String>> {
        // Pass A: bare exact token
        for key in keys {
            for idx in 0..self.vec.len() {
                let arg = match os_to_str(&self.vec[idx]) {
                    Some(a) => a,
                    None => continue,
                };
                if arg == *key {
                    if idx + 1 >= self.vec.len() {
                        return Err(AppError::plain(format!(
                            "the '{}' option doesn't have an associated value",
                            key
                        )));
                    }
                    let val_os = self.vec[idx + 1].clone();
                    let val = val_os.into_string().map_err(|_| {
                        AppError::plain("argument is not a UTF-8 string".to_string())
                    })?;
                    self.vec.drain(idx..=idx + 1);
                    return Ok(Some(val));
                }
            }
        }
        // Pass B: prefix forms
        for key in keys {
            let is_short = key.len() == 2 && key.starts_with('-');
            for idx in 0..self.vec.len() {
                let arg = match os_to_str(&self.vec[idx]) {
                    Some(a) => a.to_string(),
                    None => continue,
                };
                if is_short {
                    if arg.len() > 2 && arg.starts_with(key) {
                        let rest = &arg[2..];
                        let value = if let Some(stripped) = rest.strip_prefix('=') {
                            stripped
                        } else {
                            rest
                        };
                        if value.is_empty() {
                            return Err(AppError::plain(format!(
                                "the '{}' option doesn't have an associated value",
                                key
                            )));
                        }
                        let value = value.to_string();
                        self.vec.remove(idx);
                        return Ok(Some(value));
                    }
                } else {
                    let prefix = format!("{}=", key);
                    if arg.starts_with(&prefix) {
                        let value = &arg[prefix.len()..];
                        if value.is_empty() {
                            return Err(AppError::plain(format!(
                                "the '{}' option doesn't have an associated value",
                                key
                            )));
                        }
                        let value = value.to_string();
                        self.vec.remove(idx);
                        return Ok(Some(value));
                    }
                }
            }
        }
        Ok(None)
    }

    /// Special handling for the long-only --fallback-oob option:
    /// a bare token with no following argument is left in place.
    fn opt_value_fallback(&mut self) -> AppResult<Option<String>> {
        let key = "--fallback-oob";
        for idx in 0..self.vec.len() {
            let arg = match os_to_str(&self.vec[idx]) {
                Some(a) => a,
                None => continue,
            };
            if arg == key {
                if idx + 1 >= self.vec.len() {
                    return Ok(None);
                }
                let val_os = self.vec[idx + 1].clone();
                let val = val_os
                    .into_string()
                    .map_err(|_| AppError::plain("argument is not a UTF-8 string".to_string()))?;
                self.vec.drain(idx..=idx + 1);
                return Ok(Some(val));
            }
        }
        let prefix = "--fallback-oob=";
        for idx in 0..self.vec.len() {
            let arg = match os_to_str(&self.vec[idx]) {
                Some(a) => a.to_string(),
                None => continue,
            };
            if arg.starts_with(prefix) {
                let value = arg[prefix.len()..].to_string();
                self.vec.remove(idx);
                return Ok(Some(value));
            }
        }
        Ok(None)
    }

    fn opt_parsed<T>(
        &mut self,
        keys: &[&str],
        parse: impl Fn(&str) -> Result<T, String>,
    ) -> AppResult<Option<T>> {
        match self.opt_value(keys)? {
            None => Ok(None),
            Some(v) => {
                let parsed = parse(&v).map_err(|detail| {
                    AppError::plain(format!("failed to parse '{}': {}", v, detail))
                })?;
                Ok(Some(parsed))
            }
        }
    }
}

fn parse_trim(s: &str) -> Result<Trim, String> {
    match s {
        "l" | "L" => Ok(Trim::Left),
        "r" | "R" => Ok(Trim::Right),
        "b" | "B" => Ok(Trim::Both),
        _ => Err("Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth".to_string()),
    }
}

pub fn parse_args() -> AppResult<ParseOutcome> {
    let raw: Vec<OsString> = std::env::args_os().skip(1).collect();
    let mut args = Args { vec: raw };

    if args.contains(&["-h", "--help"]) {
        return Ok(ParseOutcome::Help);
    }
    if args.contains(&["-V", "--version"]) {
        return Ok(ParseOutcome::Version);
    }

    let fields: Option<BoundsSpec> = args.opt_parsed(&["-f", "--fields"], parse_bounds_spec)?;
    let characters: Option<BoundsSpec> =
        args.opt_parsed(&["-c", "--characters"], parse_bounds_spec)?;
    let bytes: Option<BoundsSpec> = args.opt_parsed(&["-b", "--bytes"], parse_bounds_spec)?;
    let lines: Option<BoundsSpec> = args.opt_parsed(&["-l", "--lines"], parse_bounds_spec)?;
    let delimiter: Option<String> = args.opt_value(&["-d", "--delimiter"])?;
    let greedy = args.contains(&["-g", "--greedy-delimiter"]);
    let replace: Option<String> = args.opt_value(&["-r", "--replace-delimiter"])?;
    let fixed_memory: Option<u64> = args.opt_parsed(&["-M", "--fixed-memory"], |s| {
        s.parse::<u64>().map_err(|e| e.to_string())
    })?;
    let join_flag = args.contains(&["-j", "--join"]);
    let no_join_flag = args.contains(&["--no-join"]);
    let json = args.contains(&["--json"]);
    let regex_str: Option<String> = args.opt_value(&["-e", "--regex"])?;
    let compress = args.contains(&["-p", "--compress-delimiter"]);
    let only_delimited = args.contains(&["-s", "--only-delimited"]);
    let complement = args.contains(&["-m", "--complement"]);
    let trim: Option<Trim> = args.opt_parsed(&["-t", "--trim"], parse_trim)?;
    let zero = args.contains(&["-z", "--zero-terminated"]);
    let fallback_oob: Option<String> = args.opt_value_fallback()?;
    let no_mmap = args.contains(&["--no-mmap"]);

    // Remaining arguments
    let remaining = std::mem::take(&mut args.vec);
    let mut path: Option<PathBuf> = None;
    if remaining.len() == 1 {
        let tok = &remaining[0];
        match tok.to_str() {
            None => {
                // a lone non-UTF-8 token is ignored (stdin)
            }
            Some(s) if s.starts_with('-') => {
                return Err(unexpected_error(&remaining));
            }
            Some(s) => {
                path = Some(PathBuf::from(s));
            }
        }
    } else if !remaining.is_empty() {
        return Err(unexpected_error(&remaining));
    }

    if let Some(p) = &path {
        if !p.exists() {
            return Err(AppError::runtime(format!(
                "The file \"{}\" does not exist",
                p.display()
            )));
        }
        if !p.is_file() {
            return Err(AppError::runtime(format!(
                "The path \"{}\" is not a file",
                p.display()
            )));
        }
    }

    let bounds = if let Some(b) = fields.clone() {
        b
    } else if let Some(b) = characters.clone() {
        b
    } else if let Some(b) = bytes.clone() {
        b
    } else if let Some(b) = lines.clone() {
        b
    } else {
        BoundsSpec::default_all()
    };

    let cut_type = if fields.is_some() {
        CutType::Fields
    } else if bytes.is_some() {
        CutType::Bytes
    } else if characters.is_some() {
        CutType::Characters
    } else if lines.is_some() {
        CutType::Lines
    } else {
        CutType::Fields
    };

    Ok(ParseOutcome::Opt(Opt {
        bounds,
        cut_type,
        delimiter: delimiter.unwrap_or_else(|| "\t".to_string()),
        regex_str,
        greedy,
        compress,
        only_delimited,
        zero,
        complement,
        join_flag,
        no_join_flag,
        json,
        no_mmap,
        replace,
        trim,
        fallback_oob,
        fixed_memory,
        path,
    }))
}

fn unexpected_error(remaining: &[OsString]) -> AppError {
    AppError::plain(format!(
        "tuc: unexpected arguments: {:?}\nTry 'tuc --help' for more information.",
        remaining
    ))
}
