use crate::out::Out;
use std::io::BufRead;

pub struct Ctx {
    pub opt: Opt,
    pub regex: Option<regex::bytes::Regex>,
}

#[derive(Clone)]
pub enum Delim {
    Literal(Vec<u8>),
    Regex(regex::bytes::Regex),
}

pub fn field_delim(ctx: &Ctx) -> Delim {
    match &ctx.regex {
        Some(r) => Delim::Regex(r.clone()),
        None => Delim::Literal(ctx.opt.delimiter.as_bytes().to_vec()),
    }
}

pub fn cut_delim(ctx: &Ctx) -> Delim {
    match ctx.opt.cut_type {
        CutType::Lines => Delim::Literal(b"\n".to_vec()),
        _ => field_delim(ctx),
    }
}

pub type MatchRange = (usize, usize);

pub fn find_matches(data: &[u8], delim: &Delim) -> Vec<MatchRange> {
    match delim {
        Delim::Literal(d) => {
            if d.is_empty() {
                return (0..=data.len()).map(|i| (i, i)).collect();
            }
            let mut out = Vec::new();
            let dl = d.len();
            let mut i = 0usize;
            if dl <= data.len() {
                while i + dl <= data.len() {
                    if &data[i..i + dl] == d.as_slice() {
                        out.push((i, i + dl));
                        i += dl;
                    } else {
                        i += 1;
                    }
                }
            }
            out
        }
        Delim::Regex(r) => r.find_iter(data).map(|m| (m.start(), m.end())).collect(),
    }
}

pub fn merge_adjacent(matches: &[MatchRange]) -> Vec<MatchRange> {
    let mut out: Vec<MatchRange> = Vec::new();
    for &m in matches {
        if let Some(last) = out.last_mut() {
            if m.0 == last.1 {
                last.1 = m.1;
                continue;
            }
        }
        out.push(m);
    }
    out
}

pub fn parts_from_matches(data: &[u8], matches: &[MatchRange]) -> Vec<MatchRange> {
    let mut parts = Vec::with_capacity(matches.len() + 1);
    let mut prev_end = 0usize;
    for &(s, e) in matches {
        parts.push((prev_end, s));
        prev_end = e;
    }
    parts.push((prev_end, data.len()));
    parts
}

pub fn replace_matches(slice: &[u8], delim: &Delim, replacement: &[u8]) -> Vec<u8> {
    let matches = find_matches(slice, delim);
    if matches.is_empty() {
        return slice.to_vec();
    }
    let mut out = Vec::new();
    let mut prev = 0usize;
    for &(s, e) in &matches {
        out.extend_from_slice(&slice[prev..s]);
        out.extend_from_slice(replacement);
        prev = e;
    }
    out.extend_from_slice(&slice[prev..]);
    out
}

fn trim_data(mut data: Vec<u8>, delim: &Delim, trim: Trim) -> Vec<u8> {
    match delim {
        Delim::Literal(d) => {
            // Repeatedly strip. With an empty delimiter this never
            // terminates (matching the reference behaviour).
            if matches!(trim, Trim::Left | Trim::Both) {
                while let Some(stripped) = data.strip_prefix(d.as_slice()) {
                    let new = stripped.to_vec();
                    data = new;
                }
            }
            if matches!(trim, Trim::Right | Trim::Both) {
                while let Some(stripped) = data.strip_suffix(d.as_slice()) {
                    let new = stripped.to_vec();
                    data = new;
                }
            }
            data
        }
        Delim::Regex(_) => {
            let matches = find_matches(&data, delim);
            let mut start = 0usize;
            let mut end = data.len();
            if matches!(trim, Trim::Left | Trim::Both) {
                for &(s, e) in &matches {
                    if s == start && e > s {
                        start = e;
                    } else if s > start {
                        break;
                    }
                }
            }
            if matches!(trim, Trim::Right | Trim::Both) {
                for &(s, e) in matches.iter().rev() {
                    if e == end && e > s {
                        end = s;
                    } else if e < end {
                        break;
                    }
                }
            }
            if start > end {
                start = end;
            }
            data[start..end].to_vec()
        }
    }
}

fn compress_data(data: &[u8], delim: &Delim, substitute: &[u8]) -> Vec<u8> {
    let matches = find_matches(data, delim);
    if matches.is_empty() {
        return data.to_vec();
    }
    let groups = merge_adjacent(&matches);
    let mut out = Vec::new();
    let mut prev = 0usize;
    for &(s, e) in &groups {
        out.extend_from_slice(&data[prev..s]);
        out.extend_from_slice(substitute);
        prev = e;
    }
    out.extend_from_slice(&data[prev..]);
    out
}

// ---------- bounds resolution ----------
#[derive(Clone, Debug)]
pub enum Resolved {
    /// inclusive 0-based part indexes
    Range(usize, usize),
    Fallback(Vec<u8>),
}

fn get_fallback(b: &UserBound, ctx: &Ctx) -> Option<Vec<u8>> {
    if let Some(f) = &b.fallback {
        Some(f.clone())
    } else {
        ctx.opt.fallback_oob.as_ref().map(|s| s.as_bytes().to_vec())
    }
}

fn resolve_left(l: i64, n: i64) -> Result<i64, AppError> {
    if l > 0 {
        if l > n {
            Err(AppError::oob_display(&l.to_string()))
        } else {
            Ok(l)
        }
    } else {
        let r = n + l + 1;
        if r < 1 {
            Err(AppError::oob_display(&l.to_string()))
        } else {
            Ok(r)
        }
    }
}

/// Strict resolution without fallback. None = unsatisfiable.
pub fn strict_resolve(b: &UserBound, n: usize) -> Option<(usize, usize)> {
    let n = n as i64;
    let l = resolve_left(b.left, n).ok()?;
    let r = match b.right {
        None => n,
        Some(rv) if rv > 0 => {
            if rv > n {
                return None;
            }
            rv
        }
        Some(rv) => {
            let rr = n + rv + 1;
            if rr < 1 {
                return None;
            }
            rr
        }
    };
    if l > r {
        return None;
    }
    Some(((l - 1) as usize, (r - 1) as usize))
}

fn resolve_with(
    b: &UserBound,
    n: usize,
    ctx: &Ctx,
    strict: bool,
    use_fallback: bool,
) -> AppResult<Resolved> {
    let ni = n as i64;
    let fail = |err: AppError| -> AppResult<Resolved> {
        if use_fallback {
            if let Some(f) = get_fallback(b, ctx) {
                return Ok(Resolved::Fallback(f));
            }
        }
        Err(err)
    };
    let l = match resolve_left(b.left, ni) {
        Ok(v) => v,
        Err(e) => return fail(e),
    };
    let r: i64 = match b.right {
        None => ni,
        Some(rv) if rv > 0 => {
            if strict && rv > ni {
                return fail(AppError::oob_display(&rv.to_string()));
            }
            rv.min(ni)
        }
        Some(rv) => {
            let rr = ni + rv + 1;
            if strict && rr < 1 {
                return fail(AppError::oob_display(&rv.to_string()));
            }
            rr.max(1)
        }
    };
    if l > r {
        return fail(AppError::left_gt_right());
    }
    Ok(Resolved::Range((l - 1) as usize, (r - 1) as usize))
}

pub fn resolve_clamp(b: &UserBound, n: usize, ctx: &Ctx) -> AppResult<Resolved> {
    resolve_with(b, n, ctx, false, true)
}
pub fn resolve_strict_fb(b: &UserBound, n: usize, ctx: &Ctx) -> AppResult<Resolved> {
    resolve_with(b, n, ctx, true, true)
}

// ---------- char boundaries (maximal subpart) ----------
pub fn char_parts(data: &[u8]) -> Vec<MatchRange> {
    let mut starts: Vec<usize> = vec![0];
    let mut base = 0usize;
    let mut rest = data;
    loop {
        if rest.is_empty() {
            break;
        }
        match std::str::from_utf8(rest) {
            Ok(s) => {
                for (i, _) in s.char_indices() {
                    if i != 0 {
                        starts.push(base + i);
                    }
                }
                break;
            }
            Err(e) => {
                let vu = e.valid_up_to();
                if vu > 0 {
                    let pre = std::str::from_utf8(&rest[..vu]).unwrap();
                    for (i, _) in pre.char_indices() {
                        if i != 0 {
                            starts.push(base + i);
                        }
                    }
                }
                let adv = vu + e.error_len().unwrap_or(rest.len() - vu);
                if adv == 0 {
                    break;
                }
                starts.push(base + adv);
                base += adv;
                rest = &rest[adv..];
            }
        }
    }
    if *starts.last().unwrap() != data.len() {
        starts.push(data.len());
    }
    let mut parts = Vec::new();
    for w in starts.windows(2) {
        parts.push((w[0], w[1]));
    }
    if parts.is_empty() && data.is_empty() {
        // caller handles empty data before this
    }
    parts
}

// ---------- writing ----------
#[derive(Clone, Debug)]
enum OutSeg {
    Lit(Vec<u8>),
    Piece(Resolved),
}

fn separator_bytes(ctx: &Ctx, delim: &Delim) -> Vec<u8> {
    if let Some(r) = &ctx.opt.replace {
        return r.as_bytes().to_vec();
    }
    match ctx.opt.cut_type {
        CutType::Characters => Vec::new(),
        _ => match delim {
            Delim::Literal(d) => d.clone(),
            Delim::Regex(_) => Vec::new(),
        },
    }
}

fn write_piece(
    out: &mut Out,
    ctx: &Ctx,
    data: &[u8],
    parts: &[MatchRange],
    piece: &Resolved,
    delim: &Delim,
) -> AppResult<()> {
    match piece {
        Resolved::Fallback(f) => out.write(f),
        Resolved::Range(l, r) => {
            if ctx.opt.cut_type == CutType::Characters {
                if let Some(repl) = &ctx.opt.replace {
                    for (i, p) in parts[*l..=*r].iter().enumerate() {
                        if i > 0 {
                            out.write(repl.as_bytes())?;
                        }
                        out.write(&data[p.0..p.1])?;
                    }
                    Ok(())
                } else {
                    out.write(&data[parts[*l].0..parts[*r].1])
                }
            } else {
                let raw = &data[parts[*l].0..parts[*r].1];
                if let Some(repl) = &ctx.opt.replace {
                    let owned = replace_matches(raw, delim, repl.as_bytes());
                    out.write(&owned)
                } else {
                    out.write(raw)
                }
            }
        }
    }
}

fn write_outsegs(
    out: &mut Out,
    ctx: &Ctx,
    data: &[u8],
    parts: &[MatchRange],
    segs: &[OutSeg],
    delim: &Delim,
) -> AppResult<()> {
    let total_pieces = segs.iter().filter(|s| matches!(s, OutSeg::Piece(_))).count();
    let mut piece_idx = 0usize;
    let sep = separator_bytes(ctx, delim);
    for seg in segs {
        match seg {
            OutSeg::Lit(t) => out.write(t)?,
            OutSeg::Piece(p) => {
                write_piece(out, ctx, data, parts, p, delim)?;
                if ctx.opt.join_enabled() && piece_idx + 1 < total_pieces {
                    out.write(&sep)?;
                }
                piece_idx += 1;
            }
        }
    }
    Ok(())
}

fn json_escape_write(out: &mut Out, slice: &[u8]) -> AppResult<()> {
    out.write_byte(b'"')?;
    for &b in slice {
        match b {
            b'"' => out.write(b"\\\"")?,
            b'\\' => out.write(b"\\\\")?,
            b'\n' => out.write(b"\\n")?,
            b'\r' => out.write(b"\\r")?,
            b'\t' => out.write(b"\\t")?,
            0x08 => out.write(b"\\b")?,
            0x0c => out.write(b"\\f")?,
            0x00..=0x1f => {
                out.write(format!("\\u{:04x}", b).as_bytes())?;
            }
            _ => out.write_byte(b)?,
        }
    }
    out.write_byte(b'"')
}

/// Units for JSON from a resolved piece: each part separately, fallback once.
fn write_json_pieces(
    out: &mut Out,
    ctx: &Ctx,
    data: &[u8],
    parts: &[MatchRange],
    pieces: &[Resolved],
) -> AppResult<()> {
    let _ = ctx;
    out.write_byte(b'[')?;
    for (pi, piece) in pieces.iter().enumerate() {
        let units: Vec<&[u8]> = match piece {
            Resolved::Fallback(f) => vec![f.as_slice()],
            Resolved::Range(l, r) => parts[*l..=*r]
                .iter()
                .map(|p| &data[p.0..p.1])
                .collect(),
        };
        for (ui, unit) in units.iter().enumerate() {
            json_escape_write(out, unit)?;
            let is_last = pi + 1 == pieces.len() && ui + 1 == units.len();
            if !is_last {
                out.write_byte(b',')?;
            }
        }
    }
    out.write_byte(b']')
}

fn complement_pieces(
    spec_segs: &[Seg],
    n: usize,
    is_format: bool,
) -> AppResult<Vec<OutSeg>> {
    let mut out_segs: Vec<OutSeg> = Vec::new();
    let mut total = 0usize;
    for seg in spec_segs {
        match seg {
            Seg::Lit(t) => out_segs.push(OutSeg::Lit(t.clone())),
            Seg::Bound(b) => {
                let (l, r) = match strict_resolve(b, n) {
                    Some(v) => v,
                    None => fake_panic(PANIC_LOC_CUTSTR_197, PANIC_MSG_NOCOUNT),
                };
                if l > 0 {
                    out_segs.push(OutSeg::Piece(Resolved::Range(0, l - 1)));
                    total += 1;
                }
                if r + 1 < n {
                    out_segs.push(OutSeg::Piece(Resolved::Range(r + 1, n - 1)));
                    total += 1;
                }
            }
        }
    }
    if total == 0 {
        if is_format {
            fake_panic(PANIC_LOC_USERBOUNDSLIST, PANIC_MSG_USERBOUNDSLIST);
        }
        return Err(AppError::generic("the complement is empty".to_string()));
    }
    Ok(out_segs)
}

// ---------- per-record processing ----------
fn cut_record(record: &[u8], out: &mut Out, ctx: &Ctx) -> AppResult<bool> {
    let opt = &ctx.opt;
    match opt.cut_type {
        CutType::Fields | CutType::Lines => {
            let delim = cut_delim(ctx);
            let mut data = record.to_vec();
            if let Some(t) = opt.trim {
                data = trim_data(data, &delim, t);
            }
            if opt.compress {
                let substitute: Vec<u8> = match &delim {
                    Delim::Literal(d) => d.clone(),
                    Delim::Regex(_) => opt
                        .replace
                        .as_ref()
                        .map(|s| s.as_bytes().to_vec())
                        .unwrap_or_default(),
                };
                data = compress_data(&data, &delim, &substitute);
            }
            if opt.only_delimited && find_matches(&data, &delim).is_empty() {
                return Ok(false);
            }
            if data.is_empty() {
                return Ok(true);
            }
            let raw_matches = find_matches(&data, &delim);
            let matches = if opt.greedy {
                merge_adjacent(&raw_matches)
            } else {
                raw_matches
            };
            let parts = parts_from_matches(&data, &matches);
            let n = parts.len();
            let strict = opt.cut_type == CutType::Lines;
            if opt.json {
                if opt.complement {
                    let out_segs = complement_pieces(&opt.bounds.segs, n, opt.bounds.is_format)?;
                    let pieces: Vec<Resolved> = out_segs
                        .iter()
                        .filter_map(|s| match s {
                            OutSeg::Piece(p) => Some(p.clone()),
                            _ => None,
                        })
                        .collect();
                    write_json_pieces(out, ctx, &data, &parts, &pieces)?;
                } else {
                    // resolve all bounds first? No: write streaming with
                    // comma-after-unit semantics: we resolve piece by piece
                    // but need pieces list for last-unit detection.
                    // We resolve lazily below in json streaming function.
                    write_json_streaming(out, ctx, &data, &parts, strict)?;
                }
            } else if opt.complement {
                let out_segs = complement_pieces(&opt.bounds.segs, n, opt.bounds.is_format)?;
                write_outsegs(out, ctx, &data, &parts, &out_segs, &delim)?;
            } else {
                let total = opt.bounds.bounds().len();
                let mut bi = 0usize;
                let sep = separator_bytes(ctx, &delim);
                for seg in &opt.bounds.segs {
                    match seg {
                        Seg::Lit(t) => out.write(t)?,
                        Seg::Bound(b) => {
                            let piece = if strict {
                                resolve_strict_fb(b, n, ctx)?
                            } else {
                                resolve_clamp(b, n, ctx)?
                            };
                            write_piece(out, ctx, &data, &parts, &piece, &delim)?;
                            if opt.join_enabled() && bi + 1 < total {
                                out.write(&sep)?;
                            }
                            bi += 1;
                        }
                    }
                }
            }
            Ok(true)
        }
        CutType::Characters => {
            if record.is_empty() {
                return Ok(true);
            }
            let delim = Delim::Literal(Vec::new());
            let parts = char_parts(record);
            let n = parts.len();
            if opt.json {
                if opt.complement {
                    let out_segs =
                        complement_pieces(&opt.bounds.segs, n, opt.bounds.is_format)?;
                    let pieces: Vec<Resolved> = out_segs
                        .iter()
                        .filter_map(|s| match s {
                            OutSeg::Piece(p) => Some(p.clone()),
                            _ => None,
                        })
                        .collect();
                    write_json_pieces(out, ctx, record, &parts, &pieces)?;
                } else {
                    write_json_streaming(out, ctx, record, &parts, false)?;
                }
            } else if opt.complement {
                let out_segs = complement_pieces(&opt.bounds.segs, n, opt.bounds.is_format)?;
                write_outsegs(out, ctx, record, &parts, &out_segs, &delim)?;
            } else {
                let has_range = opt.bounds.bounds().iter().any(|b| b.is_range());
                let total = opt.bounds.bounds().len();
                let mut bi = 0usize;
                let sep = separator_bytes(ctx, &delim);
                for seg in &opt.bounds.segs {
                    match seg {
                        Seg::Lit(t) => out.write(t)?,
                        Seg::Bound(b) => {
                            let piece = if has_range {
                                match strict_resolve(b, n) {
                                    Some((l, r)) => Resolved::Range(l, r),
                                    None => {
                                        fake_panic(PANIC_LOC_CUTSTR_224, PANIC_MSG_NOCOUNT)
                                    }
                                }
                            } else {
                                resolve_clamp(b, n, ctx)?
                            };
                            write_piece(out, ctx, record, &parts, &piece, &delim)?;
                            if opt.join_enabled() && bi + 1 < total {
                                out.write(&sep)?;
                            }
                            bi += 1;
                        }
                    }
                }
            }
            Ok(true)
        }
        CutType::Bytes => unreachable!(),
    }
}

/// JSON with lazy per-bound resolution so that commas are written after
/// each unit except a possible last piece's last unit. On a resolution
/// error of a later bound, the comma after the previous unit remains.
fn write_json_streaming(
    out: &mut Out,
    ctx: &Ctx,
    data: &[u8],
    parts: &[MatchRange],
    strict: bool,
) -> AppResult<()> {
    let opt = &ctx.opt;
    let n = parts.len();
    let bounds = opt.bounds.bounds();
    let total = bounds.len();
    let chars_has_range = opt.cut_type == CutType::Characters
        && bounds.iter().any(|b| b.is_range());
    out.write_byte(b'[')?;
    for (bi, b) in bounds.iter().enumerate() {
        let piece: Resolved = if chars_has_range {
            match strict_resolve(b, n) {
                Some((l, r)) => Resolved::Range(l, r),
                None => fake_panic(PANIC_LOC_CUTSTR_224, PANIC_MSG_NOCOUNT),
            }
        } else if strict {
            resolve_strict_fb(b, n, ctx)?
        } else {
            resolve_clamp(b, n, ctx)?
        };
        let units: Vec<&[u8]> = match &piece {
            Resolved::Fallback(f) => vec![f.as_slice()],
            Resolved::Range(l, r) => parts[*l..=*r]
                .iter()
                .map(|p| &data[p.0..p.1])
                .collect(),
        };
        for (ui, unit) in units.iter().enumerate() {
            json_escape_write(out, unit)?;
            let is_last = bi + 1 == total && ui + 1 == units.len();
            if !is_last {
                out.write_byte(b',')?;
            }
        }
    }
    out.write_byte(b']')
}

pub fn process_generic<R: BufRead>(reader: &mut R, out: &mut Out, ctx: &Ctx) -> AppResult<()> {
    let term = ctx.opt.eol();
    loop {
        let mut buf = Vec::new();
        let n = reader.read_until(term, &mut buf)?;
        if n == 0 {
            break;
        }
        let had_term = buf.last() == Some(&term);
        if had_term {
            buf.pop();
        }
        if term == b'\n' && had_term && buf.last() == Some(&b'\r') {
            buf.pop();
        }
        let wrote = cut_record(&buf, out, ctx)?;
        if wrote {
            out.write_byte(term)?;
        }
    }
    Ok(())
}

// ---------- bytes mode ----------
pub fn process_bytes<R: std::io::Read>(reader: &mut R, out: &mut Out, ctx: &Ctx) -> AppResult<()> {
    let mut data = Vec::new();
    // Read errors are ignored in bytes mode.
    let _ = reader.read_to_end(&mut data);
    if data.is_empty() {
        return Ok(());
    }
    let n = data.len();
    for seg in &ctx.opt.bounds.segs {
        match seg {
            Seg::Lit(t) => out.write(t)?,
            Seg::Bound(b) => {
                // fallbacks are ignored in bytes mode
                let piece = resolve_with(b, n, ctx, false, false)?;
                match piece {
                    Resolved::Range(l, r) => {
                        out.write(&data[l..=r])?;
                    }
                    Resolved::Fallback(_) => unreachable!(),
                }
            }
        }
    }
    Ok(())
}
