use crate::bounds::{Seg, UserBound};
use crate::engine::Ctx;
use crate::errors::{AppError, AppResult};
use crate::out::Out;
use std::io::BufRead;

pub fn can_stream(bounds: &crate::bounds::BoundsSpec) -> bool {
    let bs = bounds.bounds();
    for b in &bs {
        if b.left <= 0 {
            return false;
        }
        if let Some(r) = b.right {
            if r <= 0 {
                return false;
            }
        }
    }
    for i in 1..bs.len() {
        if bs[i].left < bs[i - 1].effective_right() {
            return false;
        }
    }
    true
}

struct LineReader<'a, R: BufRead> {
    reader: &'a mut R,
    zero: bool,
    idx: i64,
    cur: Option<Vec<u8>>,
    eof: bool,
}

impl<'a, R: BufRead> LineReader<'a, R> {
    fn new(reader: &'a mut R, zero: bool) -> Self {
        LineReader {
            reader,
            zero,
            idx: 0,
            cur: None,
            eof: false,
        }
    }

    /// Read the next line. Returns false on EOF.
    fn advance_one(&mut self) -> AppResult<bool> {
        if self.eof {
            return Ok(false);
        }
        if self.zero {
            let mut buf = Vec::new();
            let n = self.reader.read_until(0, &mut buf)?;
            if n == 0 {
                self.eof = true;
                return Ok(false);
            }
            if buf.last() == Some(&0u8) {
                buf.pop();
            }
            self.idx += 1;
            self.cur = Some(buf);
            Ok(true)
        } else {
            let mut s = String::new();
            let n = self.reader.read_line(&mut s)?;
            if n == 0 {
                self.eof = true;
                return Ok(false);
            }
            if s.ends_with('\n') {
                s.pop();
            }
            self.idx += 1;
            self.cur = Some(s.into_bytes());
            Ok(true)
        }
    }

    fn seek(&mut self, target: i64) -> AppResult<bool> {
        if self.cur.is_some() && self.idx == target {
            return Ok(true);
        }
        while self.idx < target {
            if !self.advance_one()? {
                return Ok(false);
            }
        }
        Ok(self.idx == target)
    }
}

pub fn process_lines_streaming<R: BufRead>(
    reader: &mut R,
    out: &mut Out,
    ctx: &Ctx,
) -> AppResult<()> {
    let opt = &ctx.opt;
    let term = opt.eol();
    let join = opt.join_enabled();
    let segs = &opt.bounds.segs;
    let mut lr = LineReader::new(reader, opt.zero);

    // Prime the first line if the first segment is a literal.
    if let Some(Seg::Lit(_)) = segs.first() {
        if !lr.advance_one()? {
            // No input lines at all: everything is dropped, final EOL only.
            out.write_byte(term)?;
            return Ok(());
        }
    }

    let mut stop_all = false;
    for (si, seg) in segs.iter().enumerate() {
        let is_last = si + 1 == segs.len();
        match seg {
            Seg::Lit(t) => {
                out.write(t)?;
                if join && !is_last {
                    out.write_byte(term)?;
                }
            }
            Seg::Bound(b) => {
                if handle_bound(&mut lr, out, b, term, join, is_last)? {
                    // returns true if an unbounded range consumed the input
                    stop_all = true;
                    break;
                }
            }
        }
    }
    let _ = stop_all;
    out.write_byte(term)?;
    Ok(())
}

/// Returns Ok(true) if processing should stop (unbounded range reached EOF).
fn handle_bound<R: BufRead>(
    lr: &mut LineReader<R>,
    out: &mut Out,
    b: &UserBound,
    term: u8,
    join: bool,
    is_last: bool,
) -> AppResult<bool> {
    if !b.is_range() {
        let target = b.left;
        if !lr.seek(target)? {
            return Err(AppError::oob_display(&target.to_string()));
        }
        let line = lr.cur.clone().unwrap_or_default();
        out.write(&line)?;
        if join && !is_last {
            out.write_byte(term)?;
        }
        return Ok(false);
    }
    match b.right {
        Some(right) => {
            let disp = format!("{}:{}", b.left, right);
            if !lr.seek(b.left)? {
                return Err(AppError::oob_display(&disp));
            }
            loop {
                let line = lr.cur.clone().unwrap_or_default();
                out.write(&line)?;
                if lr.idx >= right {
                    break;
                }
                if !lr.advance_one()? {
                    return Err(AppError::oob_display(&disp));
                }
                out.write_byte(term)?;
            }
            if join && !is_last {
                out.write_byte(term)?;
            }
            Ok(false)
        }
        None => {
            // Unbounded: consume to EOF. If its left is beyond EOF the
            // segment produces no output, and remaining segments are dropped.
            if lr.seek(b.left)? {
                loop {
                    let line = lr.cur.clone().unwrap_or_default();
                    out.write(&line)?;
                    if !lr.advance_one()? {
                        break;
                    }
                    out.write_byte(term)?;
                }
            }
            Ok(true)
        }
    }
}
