use crate::bounds::{BoundsSpec, Seg};
use crate::engine::Ctx;
use crate::errors::{AppError, AppResult};
use crate::out::Out;
use std::io::BufRead;

#[derive(Clone, Debug)]
enum FastSeg {
    Lit(Vec<u8>),
    Single { idx: i64, fb: Option<Vec<u8>> },
    Range { from: i64, to: Option<i64>, fb: Option<Vec<u8>> },
}

fn convert(spec: &BoundsSpec) -> AppResult<Vec<FastSeg>> {
    let bs = spec.bounds();
    let err = || {
        AppError::runtime("Bounds cannot be converted to ForwardBounds".to_string())
    };
    for b in &bs {
        if b.left <= 0 {
            return Err(err());
        }
        if let Some(r) = b.right {
            if r <= 0 {
                return Err(err());
            }
        }
    }
    for i in 1..bs.len() {
        let prev = bs[i - 1];
        let cur = bs[i];
        if !(cur.left > prev.left && cur.left >= prev.effective_right()) {
            return Err(err());
        }
    }
    let mut segs: Vec<FastSeg> = Vec::new();
    for seg in &spec.segs {
        match seg {
            Seg::Lit(t) => segs.push(FastSeg::Lit(t.clone())),
            Seg::Bound(b) => {
                if !b.is_range() {
                    segs.push(FastSeg::Single {
                        idx: b.left,
                        fb: b.fallback.clone(),
                    });
                } else {
                    // Merge with a directly preceding range that touches
                    // this one at its right endpoint.
                    if let Some(FastSeg::Range { to, .. }) = segs.last_mut() {
                        if *to == Some(b.left) {
                            *to = b.right;
                            continue;
                        }
                    }
                    segs.push(FastSeg::Range {
                        from: b.left,
                        to: b.right,
                        fb: b.fallback.clone(),
                    });
                }
            }
        }
    }
    Ok(segs)
}

struct State<'a> {
    segs: &'a [FastSeg],
    seg_i: usize,
    field_idx: i64,
    single_satisfied: bool,
    ctx: &'a Ctx,
    delim: u8,
    term: u8,
}

impl<'a> State<'a> {
    fn head(&self) -> Option<&FastSeg> {
        self.segs.get(self.seg_i)
    }
    fn sep_bytes(&self) -> Vec<u8> {
        match &self.ctx.opt.replace {
            Some(r) => r.as_bytes().to_vec(),
            None => vec![self.delim],
        }
    }
    fn process_lits(&mut self, out: &mut Out) -> AppResult<()> {
        while let Some(FastSeg::Lit(t)) = self.head() {
            let t = t.clone();
            out.write(&t)?;
            self.seg_i += 1;
        }
        Ok(())
    }

    fn on_data_byte(&mut self, out: &mut Out, b: u8) -> AppResult<()> {
        match self.head() {
            Some(FastSeg::Single { idx, .. }) if *idx == self.field_idx => {
                self.single_satisfied = true;
                out.write_byte(b)?;
            }
            Some(FastSeg::Range { from, to, .. }) => {
                if self.field_idx >= *from && to.map_or(true, |t| self.field_idx <= t) {
                    out.write_byte(b)?;
                }
            }
            _ => {}
        }
        Ok(())
    }

