        let ending = self.field_idx;
        let new_field = ending + 1;
        // Internal range delimiter
        let mut internal_written = false;
        if let Some(FastSeg::Range { from, to, .. }) = self.head() {
            if ending >= *from && to.map_or(true, |t| ending < t) {
                let sep = self.sep_bytes();
                out.write(&sep)?;
                internal_written = true;
            }
        }
        // Completion of the head segment at the ending field
        let completes = match self.head() {
            Some(FastSeg::Single { idx, .. }) => {
                *idx == ending && self.single_satisfied
            }
            Some(FastSeg::Range { to, .. }) => *to == Some(ending),
            _ => false,
        };
        if completes {
            self.seg_i += 1;
            self.single_satisfied = false;
            self.process_lits(out)?;
        }
        // Entering the new field
        if !internal_written {
            let active = match self.head() {
                Some(FastSeg::Single { idx, .. }) => *idx == new_field,
                Some(FastSeg::Range { from, to, .. }) => {
                    new_field >= *from && to.map_or(true, |t| new_field <= t)
                }
                _ => false,
            };
            if active {
                if self.ctx.opt.join_enabled() {
                    let sep = self.sep_bytes();
                    out.write(&sep)?;
                }
                if matches!(self.head(), Some(FastSeg::Single { .. })) {
                    self.single_satisfied = true;
                }
            }
        }
        self.field_idx = new_field;
        Ok(())
    }

    fn finalize(&mut self, out: &mut Out) -> AppResult<()> {
        loop {
            match self.head().cloned() {
                None => break,
                Some(FastSeg::Lit(t)) => {
                    out.write(&t)?;
                    self.seg_i += 1;
                }
                Some(FastSeg::Single { idx, fb }) => {
                    if self.single_satisfied {
                        self.seg_i += 1;
                        self.single_satisfied = false;
                    } else if let Some(f) = self.pick_fb(&fb) {
                        out.write(&f)?;
                        self.seg_i += 1;
                    } else {
                        return Err(AppError::oob_display(&idx.to_string()));
                    }
                }
