                    let reached = match to {
                        None => true,
                        Some(t) => self.field_idx >= t,
                    };
                    if reached {
                        self.seg_i += 1;
                    } else if let Some(f) = self.pick_fb(&fb) {
                        out.write(&f)?;
                        self.seg_i += 1;
                    } else {
                        return Err(AppError::oob_display(&from.to_string()));
                    }
                }
            }
        }
        out.write_byte(self.term)
    }

    fn pick_fb(&self, fb: &Option<Vec<u8>>) -> Option<Vec<u8>> {
        if let Some(f) = fb {
            Some(f.clone())
        } else {
            self.ctx
                .opt
                .fallback_oob
                .as_ref()
                .map(|s| s.as_bytes().to_vec())
        }
    }
}

pub fn process_fast<R: BufRead>(
    reader: &mut R,
