{"command":"cat > src/main.rs <<'EOF'
mod bounds;
mod cli;
mod engine;
mod errors;
mod fast;
mod lines;
mod out;

use cli::{CutType, Opt, ParseOutcome};
use engine::Ctx;
use errors::{AppError, AppResult};
use out::Out;
use std::io::{BufReader, IsTerminal, Read};
use std::process::ExitCode;

fn use_colors() -> bool {
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    match std::env::var("TERM") {
        Ok(t) if !t.is_empty() && t != "dumb" => {}
        _ => return false,
    }
    std::io::stdout().is_terminal()
}

fn main() -> ExitCode {
    let mut out = Out::new();
    match run(&mut out) {
        Ok(()) => match out.flush() {
            Ok(()) => ExitCode::from(0),
            Err(e) => {
                if e.is_broken_pipe() {
                    ExitCode::from(0)
                } else {
                    eprint!("{}", e.render());
                    ExitCode::from(1)
                }
            }
        },
        Err(e) => {
            if e.is_broken_pipe() {
                return ExitCode::from(0);
            }
            out.flush_ignore();
            eprint!("{}", e.render());
            ExitCode::from(1)
        }
    }
}

fn run(out: &mut Out) -> AppResult<()> {
    if std::env::args_os().len() <= 1 {
        let text: &[u8] = if use_colors() {
            include_bytes!("../assets/greet_color.txt")
        } else {
            include_bytes!("../assets/greet_plain.txt")
        };
        out.write(text)?;
        return Ok(());
    }
    let opt = match cli::parse_args()? {
        ParseOutcome::Help => {
            let text: &[u8] = if use_colors() {
                include_bytes!("../assets/help_color.txt")
            } else {
                include_bytes!("../assets/help_plain.txt")
            };
            out.write(text)?;
            return Ok(());
        }
        ParseOutcome::Version => {
            out.write(b"tuc 1.3.0\n")?;
            return Ok(());
        }
        ParseOutcome::Opt(o) => o,
    };
    let ctx = validate(opt)?;
    dispatch(out, &ctx)
}

fn validate(opt: Opt) -> AppResult<Ctx> {
    if opt.fixed_memory == Some(0) {
        return Err(AppError::runtime(
            "--fixed-memory cannot be 0".to_string(),
        ));
    }
    if opt.join_flag && opt.no_join_flag {
        return Err(AppError::runtime(
            "It's not possible to use --join and --no-join simultaneously".to_string(),
        ));
    }
    if opt.replace.is_some() && opt.no_join_flag {
        return Err(AppError::runtime(
            "You can't pass --no-join when using --replace, which implies --join".to_string(),
        ));
    }
    if opt.json && opt.replace.is_some() {
        return Err(AppError::runtime(
            "The use of --replace with --json is not supported".to_string(),
        ));
