import sys, random; sys.path.insert(0,"/tmp")
from diff import compare, run
def gen(seed, count):
    rng=random.Random(seed)
    def bound():
        kind=rng.random()
        vals=["1","2","3","4","9","-1","-2","-9","0","99"]
        if kind<0.4: return rng.choice(vals)
        if kind<0.65:
            l=rng.choice(vals+[""]); r=rng.choice(vals+[""])
            return f"{l}:{r}"
        return rng.choice(vals)
    def spec():
        if rng.random()<0.25:
            # format
            parts=[]
            for _ in range(rng.randint(1,3)):
                if rng.random()<0.5: parts.append(rng.choice(["x"," ","-","{{","}}","ab"]))
                else: parts.append("{"+bound()+("=FB" if rng.random()<0.2 else "")+"}")
            return ''.join(parts)
        bs=[]
        for _ in range(rng.randint(1,3)):
            b=bound()
            if rng.random()<0.2: b+="="+rng.choice(["FB","","zz"])
            bs.append(b)
        return ','.join(bs)
    def inp():
        n=rng.randint(0,4)
        lines=[]
        alpha="abc-xyz09\t "
        for _ in range(n):
            lines.append(''.join(rng.choice(alpha) for _ in range(rng.randint(0,9))))
        term=rng.choice(["\n","\n","\x00"])
        data=term.join(lines)
        if lines and rng.random()<0.7: data+=term
        return data.encode()
    cases=[]
    for i in range(count):
        args=[]
        # mode
        args += [rng.choice(["-f","-c","-b","-l"]), spec()]
        if rng.random()<0.7:
            args += rng.choice([["-d","-"],["-d","\t"],["-d",""],["-d","ab"],["-e","[0-9]"],["-e","-"],["-e","x*"],["-e","[ab]+"]])
        for flag,prob in [("-j",.25),("--no-join",.08),("-g",.2),("-p",.15),("-s",.15),("-m",.15),("-z",.15),("--json",.12),("--no-mmap",.1)]:
            if rng.random()<prob: args.append(flag)
        if rng.random()<0.2: args+=["-r",rng.choice(["X","","--","ab"])]
        if rng.random()<0.12: args+=["-t",rng.choice(["l","r","b","x"])]
        if rng.random()<0.12: args+=["--fallback-oob",rng.choice(["FB",""])]
        if rng.random()<0.08: args+=["-M",rng.choice(["1","2"])]
        rng.shuffle(args) if False else None
        cases.append((args, inp()))
    return cases
seed=int(sys.argv[1]); count=int(sys.argv[2])
compare(gen(seed,count), f"fuzz-seed{seed}", show=20)
