fn has_positive_endpoint_failure(bounds: &[&UserBound], n: usize) -> bool {
    let ni = n as i64;
    // An earlier L>R failure pre-empts poisoning (it errors first in
    // sequential processing).
    for b in bounds {
        let l = resolve_left(b.left, ni);
        let left_ok = l.is_ok();
        let right_pos_fail = matches!(b.right, Some(r) if r > 0 && r > ni);
        let left_pos_fail = b.left > 0 && b.left > ni;
        if left_pos_fail || right_pos_fail {
            return true;
        }
        // L>R check (endpoints individually ok)
        if left_ok {
            let l = l.unwrap();
            let r = match b.right {
                None => Some(ni),
                Some(rv) if rv > 0 => Some(rv),
                Some(rv) => {
                    let rr = ni + rv + 1;
                    if rr >= 1 {
                        Some(rr)
                    } else {
                        None
                    }
                }
            };
            if let Some(r) = r {
                if l > r {
                    return false;
                }
            }
        }
    }
    false
}
