new='''pub fn char_parts(data: &[u8]) -> Vec<MatchRange> {
    let mut parts: Vec<MatchRange> = Vec::new();
    let mut base = 0usize;
    let mut rest = data;
    loop {
        if rest.is_empty() {
            break;
        }
        match std::str::from_utf8(rest) {
            Ok(s) => {
                let mut cur = base;
                for ch in s.chars() {
                    let l = ch.len_utf8();
                    parts.push((cur, cur + l));
                    cur += l;
                }
                break;
            }
            Err(e) => {
                let vu = e.valid_up_to();
                if vu > 0 {
                    let pre = std::str::from_utf8(&rest[..vu]).unwrap();
                    let mut cur = base;
                    for ch in pre.chars() {
                        let l = ch.len_utf8();
                        parts.push((cur, cur + l));
                        cur += l;
                    }
                }
                let adv = vu + e.error_len().unwrap_or(rest.len() - vu);
                if adv == vu {
                    // Should not happen (error_len >= 1 when not at end),
                    // but guard against an infinite loop.
                    parts.push((base + vu, base + rest.len()));
                    break;
                }
                parts.push((base + vu, base + adv));
                base += adv;
                rest = &rest[adv..];
            }
        }
    }
    parts
}
